#!/usr/bin/env node
/**
 * Fetch the five solutions' agent companions into
 * tests/solution-productionize/.corpus, for slicer.test.js.
 *
 * The companions are generated by the docs extensions at build time, so the
 * tests read real ones from a published site rather than fixtures. The corpus
 * is not committed; run this again to refresh it.
 *
 *   node tests/solution-productionize/fetch-companions.mjs [--base <site url>]
 *
 * The default base is the deploy preview that publishes the solutions.
 */
import fs from 'node:fs'
import path from 'node:path'
import { fileURLToPath } from 'node:url'

const here = path.dirname(fileURLToPath(import.meta.url))
const CORPUS = path.join(here, '.corpus')
const SLUGS = ['multiplayer-gaming', 'sports-data-fanout', 'cdc-to-lakehouse', 'disaster-recovery', 'kafka-migration']

const argv = process.argv.slice(2)
const at = argv.indexOf('--base')
const base = (at >= 0 ? argv[at + 1] : 'https://deploy-preview-248--redpanda-documentation.netlify.app').replace(/\/+$/, '')

fs.mkdirSync(CORPUS, { recursive: true })
const companions = []
for (const slug of SLUGS) {
  const url = `${base}/solutions/${slug}/agent-companion.md`
  const res = await fetch(url)
  if (!res.ok) {
    console.error(`${url}: HTTP ${res.status}`)
    process.exit(1)
  }
  const text = await res.text()
  if (!text.startsWith('# Agent companion:')) {
    console.error(`${url}: not an agent companion`)
    process.exit(1)
  }
  fs.writeFileSync(path.join(CORPUS, `${slug}.md`), text)
  companions.push({ slug, url, chars: text.length })
  console.log(`${slug}: ${text.length} characters`)
}
fs.writeFileSync(path.join(CORPUS, 'manifest.json'), JSON.stringify({ base, fetchedAt: new Date().toISOString(), companions }, null, 2) + '\n')
